/**
 * Find all tenants/organizations associated with an email address and optional role
 * @summary Resolve tenants by email and role
 */
export const resolveTenants = (
  params: ResolveTenantsParams,
  signal?: AbortSignal,
) => {
  return customInstance<TenantResolutionDTO>({
    url: `/auth/tenants/resolve`,
    method: "GET",
    params,
    signal,
  });
};

export const getResolveTenantsQueryKey = (params?: ResolveTenantsParams) => {
  return [`/auth/tenants/resolve`, ...(params ? [params] : [])] as const;
};

export const getResolveTenantsQueryOptions = <
  TData = Awaited<ReturnType<typeof resolveTenants>>,
  TError = unknown,
>(
  params: ResolveTenantsParams,
  options?: {
    query?: Partial<
      UseQueryOptions<Awaited<ReturnType<typeof resolveTenants>>, TError, TData>
    >;
  },
) => {
  const { query: queryOptions } = options ?? {};

  const queryKey = queryOptions?.queryKey ?? getResolveTenantsQueryKey(params);

  const queryFn: QueryFunction<Awaited<ReturnType<typeof resolveTenants>>> = ({
    signal,
  }) => resolveTenants(params, signal);

  return { queryKey, queryFn, ...queryOptions } as UseQueryOptions<
    Awaited<ReturnType<typeof resolveTenants>>,
    TError,
    TData
  > & { queryKey: DataTag<QueryKey, TData, TError> };
};

export type ResolveTenantsQueryResult = NonNullable<
  Awaited<ReturnType<typeof resolveTenants>>
>;
export type ResolveTenantsQueryError = unknown;

