/**
 * @summary Resolve tenants by email and role
 */

export function useResolveTenants<
  TData = Awaited<ReturnType<typeof resolveTenants>>,
  TError = unknown,
>(
  params: ResolveTenantsParams,
  options?: {
    query?: Partial<
      UseQueryOptions<Awaited<ReturnType<typeof resolveTenants>>, TError, TData>
    >;
  },
  queryClient?: QueryClient,
): UseQueryResult<TData, TError> & {
  queryKey: DataTag<QueryKey, TData, TError>;
} {
  const queryOptions = getResolveTenantsQueryOptions(params, options);

  const query = useQuery(queryOptions, queryClient) as UseQueryResult<
    TData,
    TError
  > & { queryKey: DataTag<QueryKey, TData, TError> };

  query.queryKey = queryOptions.queryKey;

  return query;
}

/**
 * DEBUG ONLY - Returns the OTP stored in Redis for the given email. Remove in production!
 * @summary Debug: Check OTP stored in Redis
 */
export const debugCheckOTP = (email: string, signal?: AbortSignal) => {
  return customInstance<DebugCheckOTP200>({
    url: `/auth/debug-otp/${email}`,
    method: "GET",
    signal,
  });
};

export const getDebugCheckOTPQueryKey = (email?: string) => {
  return [`/auth/debug-otp/${email}`] as const;
};

export const getDebugCheckOTPQueryOptions = <
  TData = Awaited<ReturnType<typeof debugCheckOTP>>,
  TError = unknown,
>(
  email: string,
  options?: {
    query?: Partial<
      UseQueryOptions<Awaited<ReturnType<typeof debugCheckOTP>>, TError, TData>
    >;
  },
) => {
  const { query: queryOptions } = options ?? {};

  const queryKey = queryOptions?.queryKey ?? getDebugCheckOTPQueryKey(email);

  const queryFn: QueryFunction<Awaited<ReturnType<typeof debugCheckOTP>>> = ({
    signal,
  }) => debugCheckOTP(email, signal);

  return {
    queryKey,
    queryFn,
    enabled: !!email,
    ...queryOptions,
  } as UseQueryOptions<
    Awaited<ReturnType<typeof debugCheckOTP>>,
    TError,
    TData
  > & { queryKey: DataTag<QueryKey, TData, TError> };
};

